108	    /**
109	     * Number of owners that must already have been created for a given day before the create
110	     * response flags a bulk sign-up. When more than this many owners already share a
111	     * {@code registrationDate}, the response's {@code bulkSignupWarning} is {@code true}.
112	     */
113	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
114	
115	    private final ClinicService clinicService;
116	
117	    private final OwnerMapper ownerMapper;
118	
119	    private final PetMapper petMapper;
120	
121	    private final VisitMapper visitMapper;
122	
123	    public OwnerRestControllerV1(ClinicService clinicService,
124	                                 OwnerMapper ownerMapper,
125	                                 PetMapper petMapper,
126	                                 VisitMapper visitMapper) {
127	        this.clinicService = clinicService;
128	        this.ownerMapper = ownerMapper;
129	        this.petMapper = petMapper;
130	        this.visitMapper = visitMapper;
131	    }
132	
133	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
134	    @Override
135	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
136	        Collection<Owner> owners;
137	        if (lastName != null) {
138	            owners = this.clinicService.findOwnerByLastName(lastName);
139	        } else {
140	            owners = this.clinicService.findAllOwners();
141	        }
142	        if (owners.isEmpty()) {
143	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
144	        }
145	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
146	    }
147	
148	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
149	    @Override
150	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
151	        Owner owner = this.clinicService.findOwnerById(ownerId);
152	        if (owner == null) {
153	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
154	        }
155	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
156	        ownerDto.setBulkSignupWarning(isBulkSignupDay(owner.getRegistrationDate()));
157	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
158	    }
159	
160	    /**
161	     * Determines whether the supplied day currently holds more than {@link #BULK_SIGNUP_WARNING_THRESHOLD}
162	     * owners sharing that {@code registrationDate}, which flags an unusually high volume of same-day
163	     * owner sign-ups.
164	     *
165	     * @param registrationDate the day to inspect, or {@code null}
166	     * @return {@code true} when more than the threshold of owners are registered on that day
167	     */
168	    private boolean isBulkSignupDay(LocalDate registrationDate) {
169	        return registrationDate != null
170	            && countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD;
171	    }
172	
173	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
174	    @Override
175	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
176	        resolveAddressFields(ownerFieldsDto);
177	        validateRequiredFields(ownerFieldsDto);
178	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
179	        HttpHeaders headers = new HttpHeaders();
180	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
181	        owner.setTelephone(TelephoneNormalizer.normalize(owner.getTelephone()));
182	        owner.setEmail(normalizeEmail(owner.getEmail()));
183	        validateRegistrationDate(owner.getRegistrationDate());
184	        if (owner.getRegistrationDate() == null) {
185	            owner.setRegistrationDate(LocalDate.now());
186	        }
187	        owner.setRegistrationDate(toBusinessDay(owner.getRegistrationDate()));
188	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
189	        owner.setHouseholdId(HouseholdNormalizer.householdId(owner.getLastName(), owner.getPostcode()));
190	        owner.setIdentityKey(buildIdentityKey(owner));
191	        if (!sharesHousehold) {
192	            rejectHouseholdDuplicate(owner.getHouseholdId());
193	        }
194	        Integer possibleDuplicateOf = sharesHousehold ? null : findPossibleDuplicate(owner);
195	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
196	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
197	        if (countOwnersInCity(owner.getCity()) >= CITY_OWNER_LIMIT) {
198	            throw new OwnerCityFullException(owner.getCity());
199	        }
200	        long ownersRegisteredOnDay = countOwnersRegisteredOn(owner.getRegistrationDate());
201	        if (ownersRegisteredOnDay >= DAILY_OWNER_LIMIT) {
202	            throw new OwnerDailyLimitException(owner.getRegistrationDate());
203	        }
204	        boolean bulkSignupWarning = ownersRegisteredOnDay > BULK_SIGNUP_WARNING_THRESHOLD;
205	        owner.setCustomerCode(buildCustomerCode(owner));
206	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
207	        owner.setHouseholdSize(countHouseholdMembers(owner.getHouseholdId()) + 1);
208	        this.clinicService.saveOwner(owner);
209	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
210	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
211	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
212	            ownerDto.getMembershipLevel(), ownerDto.getMembershipNumber());
213	        ownerDto.setBulkSignupWarning(bulkSignupWarning);
214	        headers.setLocation(UriComponentsBuilder.newInstance()
215	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
216	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
217	    }
218	
219	    /**
220	     * Canonicalizes the submitted address fields into the form that is validated, stored and
221	     * returned, before any required-field check or mapping runs. This is the single place a create
222	     * request's address input is resolved.
223	     *
224	     * <p>The structured fields are preferred over the flat input for backward compatibility: when a
225	     * non-blank {@code addressLine1} is supplied, {@code addressLine1} and the optional
226	     * {@code addressLine2} are {@link AddressNormalizer#normalize normalized} in place and the flat
227	     * {@code address} is set to the composed value - the normalized {@code addressLine1}, with a
228	     * single space and the normalized {@code addressLine2} appended when {@code addressLine2} is
229	     * present. When no structured line is supplied the flat {@code address} is normalized in place,
230	     * exactly as before. Either way everything downstream - the required-field check, the mapping onto
231	     * {@link Owner} and the response - sees the canonical address rather than the raw input. A value
232	     * that is blank only after normalization is left blank here and rejected later by
233	     * {@link #validateRequiredFields}.
234	     *
235	     * @param ownerFieldsDto the submitted owner fields, mutated in place with the resolved address
236	     */
237	    private void resolveAddressFields(OwnerFieldsDto ownerFieldsDto) {
238	        String line1 = AddressNormalizer.normalize(ownerFieldsDto.getAddressLine1());
239	        String line2 = AddressNormalizer.normalize(ownerFieldsDto.getAddressLine2());
240	        if (!line1.isEmpty()) {
241	            ownerFieldsDto.setAddressLine1(line1);
242	            ownerFieldsDto.setAddressLine2(line2.isEmpty() ? null : line2);
243	            ownerFieldsDto.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
244	        }
245	        else {
246	            ownerFieldsDto.setAddress(AddressNormalizer.normalize(ownerFieldsDto.getAddress()));
247	        }
248	    }
249	
250	    /**
251	     * Rejects an owner payload that is missing or blank in any required field. Collects the name of
252	     * every offending field and, if there is at least one, raises a {@link MissingOwnerFieldsException}
253	     * so the client receives a 400 whose {@code errors} array lists each missing field. The address is
254	     * checked in its resolved form (see {@link #resolveAddressFields}), which is satisfied by either a
255	     * non-blank {@code addressLine1} or the flat {@code address}, so a value that is blank only after
256	     * normalization is still rejected.
257	     *
258	     * @param ownerFieldsDto the submitted owner fields
259	     */
260	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
261	        List<String> missingFields = new ArrayList<>();
262	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
263	            missingFields.add("firstName");
264	        }
265	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
266	            missingFields.add("lastName");
267	        }
268	        if (!StringUtils.hasText(ownerFieldsDto.getAddress())) {
269	            missingFields.add("address");
270	        }
271	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
272	            missingFields.add("city");
273	        }
274	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
275	            missingFields.add("telephone");
276	        }
277	        if (!missingFields.isEmpty()) {
278	            throw new MissingOwnerFieldsException(missingFields);
279	        }
280	    }
281	
282	    /**
283	     * Validates an owner's optional postcode. Postcode is optional, so a missing or blank value is
284	     * accepted unchanged. When a value is supplied it must be exactly four digits; and when the owner's
285	     * city maps to a known region the postcode must fall within that region's inclusive range (checked
286	     * via {@link OwnerLocality#postcodeMatchesCity}, which owns the region table). A city with no known
287	     * region accepts any 4-digit postcode. A malformed or out-of-range postcode is rejected with a 400
288	     * whose {@code errors} array lists {@code postcode}.
289	     *
290	     * @param postcode the submitted postcode, or {@code null} when none was supplied
291	     * @param city the owner's city, whose region determines the acceptable postcode range
292	     * @throws InvalidOwnerFieldsException if a supplied postcode is not four digits or is out of range
293	     */
294	    private void validatePostcode(String postcode, String city) {
295	        if (!StringUtils.hasText(postcode)) {
296	            return;
297	        }
298	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
299	            throw new InvalidOwnerFieldsException(List.of("postcode"));
300	        }
301	        if (!OwnerLocality.postcodeMatchesCity(postcode, city)) {
302	            throw new InvalidOwnerFieldsException(List.of("postcode"));
303	        }
304	    }
305	
306	    /**
307	     * Validates an owner's optional registration date. Registration date is optional, so a missing
308	     * value is accepted (the create later defaults it to the server date). When a value is supplied
309	     * it may not lie in the future: a date later than the server's current date is rejected with a
310	     * 400 whose {@code errors} array lists {@code registrationDate}.
311	     *
312	     * @param registrationDate the submitted registration date, or {@code null} when none was supplied
313	     * @throws InvalidOwnerFieldsException if a supplied date is later than the server date
314	     */
315	    private void validateRegistrationDate(LocalDate registrationDate) {
316	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
317	            throw new InvalidOwnerFieldsException(List.of("registrationDate"));
318	        }
319	    }
320	
321	    /**
322	     * Rejects a submitted owner that would join a household which already has a member. Because the
323	     * {@code householdId} is derived deterministically from the owner's last name and postcode, any
324	     * existing owner sharing that id is the same household, so a second such owner is reported to the
325	     * client as a 409 Conflict. A request may knowingly bypass this block by opting in with
326	     * {@code sharesHousehold}, in which case this check is not performed.
327	     *
328	     * @param householdId the derived household identifier of the owner about to be created
329	     */
330	    private void rejectHouseholdDuplicate(String householdId) {
331	        boolean duplicate = this.clinicService.findAllOwners().stream()
332	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
333	        if (duplicate) {
334	            throw new DuplicateOwnerIdentityException(householdId);
335	        }
336	    }
337	
338	    /**
339	     * Derives the owner's {@code identityKey}, formatted
340	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}, where the telephone
341	     * and email have already been normalized. The household segment always carries the owner's
342	     * deterministic {@code householdId}, since owners with the same last name and postcode belong to
343	     * the same household automatically.
344	     *
345	     * @param owner the normalized owner about to be created, with its {@code householdId} already set
346	     * @return the derived identity key
347	     */
348	    private String buildIdentityKey(Owner owner) {
349	        String email = StringUtils.hasText(owner.getEmail()) ? owner.getEmail() : "";
350	        return owner.getTelephone() + "|" + email + "|" + owner.getHouseholdId();
351	    }
352	
353	    /**
354	     * Detects a soft-match duplicate for the owner about to be created. A soft match is an owner that
355	     * shares an existing owner's {@code lastName} (case-insensitively) and {@code postcode} while
356	     * having a different normalized {@code telephone}. Such an owner is still created, but is flagged
357	     * as a possible duplicate of the matching owner. This is only consulted for owners that did not
358	     * opt into a shared household: an owner that declares {@code sharesHousehold} is a known household
359	     * member, not a suspected duplicate, so it is never flagged. The comparison only applies when a
360	     * postcode was supplied, since both owners must share one; when several existing owners match, the
361	     * earliest (lowest id) is used.
362	     *
363	     * @param owner the normalized owner about to be created, with its telephone already normalized
364	     * @return the id of the matching existing owner, or {@code null} when there is no soft match
365	     */
366	    private Integer findPossibleDuplicate(Owner owner) {
367	        if (!StringUtils.hasText(owner.getPostcode())) {
368	            return null;
369	        }
370	        return this.clinicService.findAllOwners().stream()
371	            .filter(existing -> owner.getLastName().equalsIgnoreCase(existing.getLastName()))
372	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
373	            .filter(existing -> !owner.getTelephone().equals(existing.getTelephone()))
374	            .map(Owner::getId)
375	            .filter(id -> id != null)
376	            .min(Integer::compareTo)
377	            .orElse(null);
378	    }
379	
380	    /**
381	     * Normalizes an optional email address for owner creation. Email is optional, so a missing or
382	     * blank value is left untouched. When a value is supplied it must be a syntactically valid
383	     * address; the accepted value is lower-cased before it is stored and returned.
384	     *
385	     * @param email the raw email value submitted by the client, or {@code null}
386	     * @return the lower-cased email, or the original blank/{@code null} value when none was supplied
387	     * @throws InvalidOwnerFieldsException if a non-blank value is not a syntactically valid address
388	     */
389	    private String normalizeEmail(String email) {
390	        if (!StringUtils.hasText(email)) {
391	            return email;
392	        }
393	        if (!EMAIL_PATTERN.matcher(email).matches()) {
394	            throw new InvalidOwnerFieldsException(List.of("email"));
395	        }
396	        String normalized = email.toLowerCase();
397	        String domain = normalized.substring(normalized.indexOf('@') + 1);
398	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
399	            throw new InvalidOwnerFieldsException(List.of("email"));
400	        }
401	        return normalized;
402	    }
403	
404	    /**
405	     * Assigns the owner's customer code, formatted {@code <REGION>-<HASH8>}. The region is derived
406	     * from the owner's postcode (falling back to its city), and the code itself - region plus the
407	     * hash of the owner's normalized telephone and last name - is composed by {@link CustomerCode}.
408	     * When the composed code collides with an existing owner's customer code, it is de-duplicated by
409	     * appending {@code -<n>} with the smallest {@code n} of two or more that makes it unique.
410	     *
411	     * @param owner the normalized owner about to be created
412	     * @return the assigned, de-duplicated customer code
413	     */
414	    private String buildCustomerCode(Owner owner) {
415	        String region = OwnerLocality.forPostcodeAndCity(owner.getPostcode(), owner.getCity());
416	        String code = CustomerCode.forRegionAndIdentity(region, owner.getTelephone(), owner.getLastName());
417	        return deduplicateCustomerCode(code);
418	    }
419	
420	    /**
421	     * De-duplicates a freshly composed customer code against the codes of all existing owners. When
422	     * the code is already unique it is returned unchanged; otherwise {@code -<n>} is appended, using
423	     * the smallest {@code n} of two or more that yields a code no existing owner holds.
424	     *
425	     * @param code the composed customer code, before de-duplication
426	     * @return the same code when unique, otherwise the code with the smallest available {@code -<n>} suffix
427	     */
428	    private String deduplicateCustomerCode(String code) {
429	        Set<String> existingCodes = this.clinicService.findAllOwners().stream()
430	            .map(Owner::getCustomerCode)
431	            .filter(existing -> existing != null)
432	            .collect(Collectors.toSet());
433	        if (!existingCodes.contains(code)) {
434	            return code;
435	        }
436	        int suffix = 2;
437	        while (existingCodes.contains(code + "-" + suffix)) {
438	            suffix++;
439	        }
440	        return code + "-" + suffix;
441	    }
442	
443	    /**
444	     * Counts how many owners already exist that share the supplied first and last name, compared
445	     * case-insensitively. This reflects the number of namesakes present <em>before</em> the current
446	     * owner is created and is stored on the new owner as its {@code namesakeCount}.
447	     *
448	     * @param firstName the submitted owner's first name
449	     * @param lastName the submitted owner's last name
450	     * @return the number of existing owners with the same first and last name, ignoring case
451	     */
452	    private int countNamesakes(String firstName, String lastName) {
453	        return (int) this.clinicService.findAllOwners().stream()
454	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
455	                && lastName.equalsIgnoreCase(existing.getLastName()))
456	            .count();
457	    }
458	
459	    /**
460	     * Counts how many existing owners already belong to the supplied household, identified by its
461	     * {@code householdId}. Used when creating an owner to determine the household's size once the new
462	     * owner is added (this count plus one).
463	     *
464	     * @param householdId the normalized household identifier of the owner being created
465	     * @return the number of existing owners already sharing that {@code householdId}
466	     */
467	    private int countHouseholdMembers(String householdId) {
468	        return (int) this.clinicService.findAllOwners().stream()
469	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
470	            .count();
471	    }
472	
473	    /**
474	     * Counts how many owners already live in the supplied city, compared case-insensitively. Used to
475	     * enforce the per-city capacity limit when a new owner is created.
476	     *
477	     * @param city the submitted owner's city
478	     * @return the number of existing owners in that city, ignoring case
479	     */
480	    private long countOwnersInCity(String city) {
481	        return this.clinicService.findAllOwners().stream()
482	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
483	            .count();
484	    }
485	
486	    /**
487	     * Counts how many owners have already been created on the supplied registration date. Used to
488	     * enforce the per-day capacity limit when a new owner is created.
489	     *
490	     * @param registrationDate the registration date of the owner being created
491	     * @return the number of existing owners already registered on that date
492	     */
493	    /**
494	     * Rolls a registration date forward to a business day. A registration date must fall on a
495	     * business day, so when the supplied or defaulted date lands on a Saturday or Sunday it is
496	     * moved forward to the following Monday; a weekday is returned unchanged. Every value derived
497	     * from the registration date (such as the membership number's year segment) and the daily
498	     * create-limit therefore use the adjusted date.
499	     *
500	     * @param date the effective registration date, whether supplied or defaulted to the server date
501	     * @return the same date when it is a weekday, otherwise the next Monday
502	     */
503	    private LocalDate toBusinessDay(LocalDate date) {
504	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
505	            date = date.plusDays(1);
506	        }
507	        return date;
508	    }
509	
510	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
511	        return this.clinicService.findAllOwners().stream()
512	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
513	            .count();
514	    }
515	
516	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
517	    @Override
518	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
519	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
520	        if (currentOwner == null) {
521	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
522	        }
523	        currentOwner.setAddress(ownerFieldsDto.getAddress());
524	        currentOwner.setCity(ownerFieldsDto.getCity());
525	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
526	        currentOwner.setLastName(ownerFieldsDto.getLastName());
527	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
528	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
529	        this.clinicService.saveOwner(currentOwner);
530	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
531	    }
532	
533	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
534	    @Transactional
535	    @Override
536	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
537	        Owner owner = this.clinicService.findOwnerById(ownerId);
538	        if (owner == null) {
539	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
540	        }
541	        this.clinicService.deleteOwner(owner);
542	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
543	    }
544	
545	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
546	    @Override
547	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
548	        Owner owner = this.clinicService.findOwnerById(ownerId);
549	        if (owner == null) {
550	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
551	        }
552	        HttpHeaders headers = new HttpHeaders();
553	        Pet pet = petMapper.toPet(petFieldsDto);
554	        owner.setId(ownerId);
555	        pet.setOwner(owner);
556	        pet.getType().setName(null);
557	        this.clinicService.savePet(pet);
558	        PetDto petDto = petMapper.toPetDto(pet);
559	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
560	            .buildAndExpand(pet.getId()).toUri());
561	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
562	    }
563	
564	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
565	    @Override
566	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
567	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
568	        if (currentOwner != null) {
569	            Pet currentPet = this.clinicService.findPetById(petId);
570	            if (currentPet != null) {
571	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
572	                currentPet.setName(petFieldsDto.getName());
573	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
574	                this.clinicService.savePet(currentPet);
575	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
576	            }
577	        }
578	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
579	    }
580	
581	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
582	    @Override
583	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
584	        HttpHeaders headers = new HttpHeaders();
585	        Visit visit = visitMapper.toVisit(visitFieldsDto);
586	        Pet pet = new Pet();
587	        pet.setId(petId);
588	        visit.setPet(pet);
589	        this.clinicService.saveVisit(visit);
590	        VisitDto visitDto = visitMapper.toVisitDto(visit);
591	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
592	            .buildAndExpand(visit.getId()).toUri());
593	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
594	    }
595	
596	
597	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
598	    @Override
599	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
600	        Owner owner = this.clinicService.findOwnerById(ownerId);
601	        if (owner != null) {
602	            Pet pet = owner.getPet(petId);
603	            if (pet != null) {
604	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
605	            }
606	        }
607	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
608	    }
609	}
